static int adj[105][105],deg[105],matchR[105],seen[105];
static int tryk(int u){for(int q=0;q<deg[u];q++){int v=adj[u][q];if(seen[v])continue;seen[v]=1;if(matchR[v]==0||tryk(matchR[v])){matchR[v]=u;return 1;}}return 0;}
int main(void){int nL,nR,m,i;static int bu[100005],bv[100005];if(scanf("%d %d %d",&nL,&nR,&m)!=3)return 1;for(i=0;i<m;i++)scanf("%d %d",&bu[i],&bv[i]);for(i=0;i<=nL;i++)deg[i]=0;for(i=0;i<m;i++){int u=bu[i],v=bv[i];int dup=0;for(int q=0;q<deg[u];q++)if(adj[u][q]==v){dup=1;break;}if(!dup)adj[u][deg[u]++]=v;}for(i=0;i<=nR;i++)matchR[i]=0;int res=0;for(int u=1;u<=nL;u++){for(int q=0;q<=nR;q++)seen[q]=0;if(tryk(u))res++;}printf("%d\n",res);return 0;}
